           typename = std::enable_if_t<std::is_arithmetic<T>::value>>
 class Spline final {
+  // These are the constant factors for each segment of the curve.
+  // Each segment i will have the formula:
+  // f(x) = a[i] + b[i]*(x - x[i]) + c[i]*(x - x[i])^2 + d[i]*(x - x[i])^3
+  struct Segment {
+    double a;
+    double b;
+    double c;
+    double d;
+  };
+
   int num_coords;
   int num_segments;

   std::vector<int> xCp;
