-
     // Extra values used during computation
     std::vector<double> h(num_segments);
     std::vector<double> alpha(num_segments);
@@ -66,9 +65,17 @@ class Spline final {
     for (int i = 0; i < num_segments; i++)
       h[i] = xCp[i + 1] - xCp[i];

-    for (int i = 1; i < num_segments; i++)
