+      Segment& s = segments[i];
+      Segment& sn = segments[i + 1];
+
+      s.c = z[i] - mu[i] * sn.c;
+      s.b = (sn.a - s.a) / h[i] - h[i] * (sn.c + 2 * s.c) / 3.;
+      s.d = (sn.c - s.c) / (3. * h[i]);
     }
+
+    assert(static_cast<typename decltype(segments)::size_type>(num_segments) ==
